          "explanation": "计算机软件是指为运行、维护和管理计算机而编制的各种程序、数据和文档的总称。计算机软件系统按照使用功能,一般分为系统软件和应用软件两大类。系统软件是为扩大计算机的功能、提高计算机的工作效率以及为方便用户使用计算机而设计的软件,如操作系统、语言处理程序和服务程序等;应用软件是为解决某个应用领域中的具体任务而编制的程序,如文字处理软件、计算机辅助设计软件等。"
