          "explanation": "水系灭火剂的适用范围:(1) 用直流水或开花水可扑救一般固体物质的表面火灾及闪点在120°C以上的重油火灾。(2) 用雾状水可扑救阴燃物质火灾、可燃粉尘火灾、电气设备火灾。(3) 用水蒸气可以扑救封闭空间内(如船舱)的火灾。(4) 凡遇水会发生燃烧和爆炸的物质,不能用水进行扑救。"
